create policy "videos read" on storage.objects for select to anon, authenticated using (bucket_id = 'videos');
create policy "videos own upload" on storage.objects for insert to authenticated with check (bucket_id = 'videos' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "videos own delete" on storage.objects for delete to authenticated using (bucket_id = 'videos' and (storage.foldername(name))[1] = auth.uid()::text);